/* Sunset Horizon Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Sunset Horizon Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 23.98 99.77% 98.64%;
    --foreground: 346.91 5.99% 22.46%;
    --card: 300 50% 100%;
    --card-foreground: 346.91 5.99% 22.46%;
    --popover: 300 50% 100%;
    --popover-foreground: 346.91 5.99% 22.46%;
    --primary: 11.65 99.63% 69.26%;
    --primary-foreground: 300 50% 100%;
    --secondary: 8.57 99.92% 95.93%;
    --secondary-foreground: 9.91 47.44% 47.79%;
    --muted: 14.99 99.99% 96.58%;
    --muted-foreground: 24.98 4.57% 44.34%;
    --accent: 26.04 97.51% 74.4%;
    --accent-foreground: 346.91 5.99% 22.46%;
    --destructive: 355.21 77.73% 55.8%;
    --destructive-foreground: 300 50% 100%;
    --border: 14.64 99.94% 92.01%;
    --input: 14.64 99.94% 92.01%;
    --ring: 11.65 99.63% 69.26%;
    --chart-1: 11.65 99.63% 69.26%;
    --chart-2: 26.04 97.51% 74.4%;
    --chart-3: 23.84 99.96% 83.16%;
    --chart-4: 16.07 99.98% 78.04%;
    --chart-5: 9.6 55.17% 57.85%;
    --radius: 0.625rem;
    --sidebar: 14.99 99.99% 96.58%;
    --sidebar-foreground: 346.91 5.99% 22.46%;
    --sidebar-primary: 11.65 99.63% 69.26%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 26.04 97.51% 74.4%;
    --sidebar-accent-foreground: 346.91 5.99% 22.46%;
    --sidebar-border: 14.64 99.94% 92.01%;
    --sidebar-ring: 11.65 99.63% 69.26%;
    --font-sans: Montserrat, sans-serif;
    --font-serif: Merriweather, serif;
    --font-mono: Ubuntu Mono, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.09;
    --shadow-blur: 12px;
    --shadow-spread: -3px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 6px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 6px 12px -3px hsl(0 0% 0% / 0.04);
    --shadow-xs: 0px 6px 12px -3px hsl(0 0% 0% / 0.04);
    --shadow-sm:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 1px 2px -4px hsl(0 0% 0% / 0.09);
    --shadow:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 1px 2px -4px hsl(0 0% 0% / 0.09);
    --shadow-md:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 2px 4px -4px hsl(0 0% 0% / 0.09);
    --shadow-lg:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 4px 6px -4px hsl(0 0% 0% / 0.09);
    --shadow-xl:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 8px 10px -4px hsl(0 0% 0% / 0.09);
    --shadow-2xl: 0px 6px 12px -3px hsl(0 0% 0% / 0.22);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 335.7 15.57% 14.91%;
    --foreground: 21.42 29.59% 92.19%;
    --card: 323.82 10.77% 20.63%;
    --card-foreground: 21.42 29.59% 92.19%;
    --popover: 323.82 10.77% 20.63%;
    --popover-foreground: 21.42 29.59% 92.19%;
    --primary: 11.65 99.63% 69.26%;
    --primary-foreground: 300 50% 100%;
    --secondary: 325.01 9.37% 24.71%;
    --secondary-foreground: 21.42 29.59% 92.19%;
    --muted: 323.82 10.77% 20.63%;
    --muted-foreground: 22.19 21.68% 79.32%;
    --accent: 26.04 97.51% 74.4%;
    --accent-foreground: 335.7 15.57% 14.91%;
    --destructive: 355.21 77.73% 55.8%;
    --destructive-foreground: 300 50% 100%;
    --border: 325.01 9.37% 24.71%;
    --input: 325.01 9.37% 24.71%;
    --ring: 11.65 99.63% 69.26%;
    --chart-1: 11.65 99.63% 69.26%;
    --chart-2: 26.04 97.51% 74.4%;
    --chart-3: 23.84 99.96% 83.16%;
    --chart-4: 16.07 99.98% 78.04%;
    --chart-5: 9.6 55.17% 57.85%;
    --radius: 0.625rem;
    --sidebar: 335.7 15.57% 14.91%;
    --sidebar-foreground: 21.42 29.59% 92.19%;
    --sidebar-primary: 11.65 99.63% 69.26%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 26.04 97.51% 74.4%;
    --sidebar-accent-foreground: 335.7 15.57% 14.91%;
    --sidebar-border: 325.01 9.37% 24.71%;
    --sidebar-ring: 11.65 99.63% 69.26%;
    --font-sans: Montserrat, sans-serif;
    --font-serif: Merriweather, serif;
    --font-mono: Ubuntu Mono, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.09;
    --shadow-blur: 12px;
    --shadow-spread: -3px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 6px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 6px 12px -3px hsl(0 0% 0% / 0.04);
    --shadow-xs: 0px 6px 12px -3px hsl(0 0% 0% / 0.04);
    --shadow-sm:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 1px 2px -4px hsl(0 0% 0% / 0.09);
    --shadow:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 1px 2px -4px hsl(0 0% 0% / 0.09);
    --shadow-md:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 2px 4px -4px hsl(0 0% 0% / 0.09);
    --shadow-lg:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 4px 6px -4px hsl(0 0% 0% / 0.09);
    --shadow-xl:
      0px 6px 12px -3px hsl(0 0% 0% / 0.09), 0px 8px 10px -4px hsl(0 0% 0% / 0.09);
    --shadow-2xl: 0px 6px 12px -3px hsl(0 0% 0% / 0.22);
  }

}
